import React from "react";
import { MonthlyData } from "../types";

interface ExpenseTrendChartProps {
  data: MonthlyData[];
}

const ExpenseTrendChart: React.FC<ExpenseTrendChartProps> = ({ data }) => {
  const maxValue = Math.max(...data.flatMap((d) => [d.income, d.expenses]));

  return (
    <div>
      {/* Legend */}
      <div className="flex gap-4 mb-3">
        <span className="flex items-center gap-1.5 text-xs text-gray-500">
          <span className="w-2.5 h-2.5 bg-emerald-500 rounded-sm inline-block" />
          Income
        </span>
        <span className="flex items-center gap-1.5 text-xs text-gray-500">
          <span className="w-2.5 h-2.5 bg-red-200 rounded-sm inline-block" />
          Expense
        </span>
      </div>

      {/* Bars */}
      <div className="flex items-end gap-2 h-36">
        {data.map((d, i) => {
          const incH = Math.round((d.income / maxValue) * 120);
          const expH = Math.round((d.expenses / maxValue) * 120);
          return (
            <div key={i} className="flex flex-col items-center gap-1 flex-1">
              <div className="flex items-end gap-0.5" style={{ height: 120 }}>
                <div
                  className="bg-emerald-500 rounded-t w-3 transition-all"
                  style={{ height: incH }}
                />
                <div
                  className="bg-red-200 rounded-t w-3 transition-all"
                  style={{ height: expH }}
                />
              </div>
              <span className="text-[10px] text-gray-400">{d.month}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default ExpenseTrendChart;
